/**
 * Rich UI blocks attached to assistant messages. They are produced deterministically from
 * tool results (never generated by the LLM), so what the patient sees on a card is always real data.
 */
export interface SlotItem {
  start: string;
  end: string;
  time: string;
  day: string;
}

export interface CardAppointment {
  id: string;
  doctorId: string;
  doctorName: string;
  specialty: string | null;
  serviceName: string | null;
  start: string;
  end: string;
  when: string;
  status: string;
  location: string | null;
}

export type Attachment =
  | {
      type: 'slots';
      mode: 'book' | 'reschedule';
      appointmentId?: string;
      serviceId?: string | null;
      timezone: string;
      groups: { doctorId: string; doctorName: string; specialty: string | null; slots: SlotItem[] }[];
    }
  | {
      type: 'doctors';
      doctors: { id: string; name: string; specialty: string | null; bio: string | null; languages: string[]; color: string; avatarUrl: string | null }[];
    }
  | { type: 'appointment'; appointment: CardAppointment; state: 'created' | 'cancelled' | 'rescheduled' | 'info' }
  | { type: 'appointments'; purpose: 'cancel' | 'reschedule' | 'list'; items: CardAppointment[] }
  | { type: 'citations'; sources: { sourceId: string; title: string; excerpt: string; score: number }[] }
  | { type: 'services'; items: { id: string; name: string; specialty: string | null; durationMinutes: number; price: string | null }[] }
  | { type: 'handoff'; urgency: string; reason: string }
  | { type: 'emergency' }
  | { type: 'suggestions'; items: { label: string; message: string }[] };
